CREATE TABLE public.strategy_scoring_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL, version text NOT NULL UNIQUE, config jsonb NOT NULL CHECK(jsonb_typeof(config)='object'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.strategy_scoring_policies TO authenticated; GRANT ALL ON public.strategy_scoring_policies TO service_role;
ALTER TABLE public.strategy_scoring_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY scoring_policy_read ON public.strategy_scoring_policies FOR SELECT TO authenticated USING(public.account_mfa_allowed());
CREATE TRIGGER scoring_policy_immutable BEFORE UPDATE OR DELETE ON public.strategy_scoring_policies FOR EACH ROW EXECUTE FUNCTION public.prevent_evaluation_mutation();
CREATE TABLE public.strategy_integrity_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, strategy_id uuid NOT NULL REFERENCES public.strategies(id), evaluation_id uuid NOT NULL UNIQUE REFERENCES public.strategy_evaluations(id), reasons jsonb NOT NULL, status text NOT NULL DEFAULT 'quarantined' CHECK(status IN('quarantined','appealed','dismissed','upheld')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT SELECT ON public.strategy_integrity_cases TO authenticated; GRANT ALL ON public.strategy_integrity_cases TO service_role;
ALTER TABLE public.strategy_integrity_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrity_case_read ON public.strategy_integrity_cases FOR SELECT TO authenticated USING(public.account_mfa_allowed() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE TABLE public.strategy_integrity_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.strategy_integrity_cases(id), user_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL CHECK(action IN('quarantined','appealed','dismissed','upheld')), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.strategy_integrity_events TO authenticated; GRANT ALL ON public.strategy_integrity_events TO service_role;
ALTER TABLE public.strategy_integrity_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY integrity_event_read ON public.strategy_integrity_events FOR SELECT TO authenticated USING(public.account_mfa_allowed() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE TRIGGER integrity_events_immutable BEFORE UPDATE OR DELETE ON public.strategy_integrity_events FOR EACH ROW EXECUTE FUNCTION public.prevent_evaluation_mutation();
CREATE FUNCTION public.quarantine_rejected_evaluation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF NEW.status='REJECTED' THEN INSERT INTO public.strategy_integrity_cases(user_id,strategy_id,evaluation_id,reasons) VALUES(NEW.user_id,NEW.strategy_id,NEW.id,coalesce(NEW.report->'violations','[]'::jsonb)) RETURNING id INTO cid; INSERT INTO public.strategy_integrity_events(case_id,user_id,actor_id,action,message) VALUES(cid,NEW.user_id,NEW.user_id,'quarantined','Independent evaluation rejected inconsistent evidence; new strategy entries quarantined.'); UPDATE public.trading_bots SET status='paused',status_reason='Integrity quarantine: new entries blocked; exits remain available' WHERE user_id=NEW.user_id AND strategy_id=NEW.strategy_id AND status IN('running','paper_trading'); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.quarantine_rejected_evaluation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER evaluation_integrity_quarantine AFTER INSERT ON public.strategy_evaluations FOR EACH ROW EXECUTE FUNCTION public.quarantine_rejected_evaluation();
CREATE FUNCTION public.guard_quarantined_strategy_entry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF NEW.idempotency_key LIKE '%:exit:%' OR NEW.bot_id IS NULL THEN RETURN NEW; END IF; SELECT strategy_id INTO sid FROM public.trading_bots WHERE id=NEW.bot_id AND user_id=NEW.user_id; IF EXISTS(SELECT 1 FROM public.strategy_integrity_cases WHERE user_id=NEW.user_id AND strategy_id=sid AND status IN('quarantined','appealed','upheld')) THEN RAISE EXCEPTION 'Strategy integrity quarantine blocks new entries; recovery exits remain available'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_quarantined_strategy_entry() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER order_strategy_quarantine BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_quarantined_strategy_entry();
CREATE FUNCTION public.guard_quarantined_bot_start() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IN('running','paper_trading') AND EXISTS(SELECT 1 FROM public.strategy_integrity_cases WHERE user_id=NEW.user_id AND strategy_id=NEW.strategy_id AND status IN('quarantined','appealed','upheld')) THEN RAISE EXCEPTION 'Strategy is quarantined; independent review required'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_quarantined_bot_start() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bot_strategy_quarantine BEFORE INSERT OR UPDATE OF status,strategy_id ON public.trading_bots FOR EACH ROW EXECUTE FUNCTION public.guard_quarantined_bot_start();
CREATE FUNCTION public.appeal_strategy_integrity(_case uuid,_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.strategy_integrity_cases%ROWTYPE; BEGIN IF NOT public.account_mfa_allowed() THEN RAISE EXCEPTION 'Account verification required'; END IF; IF length(trim(_message))<10 OR length(_message)>2000 THEN RAISE EXCEPTION 'Appeal must be 10 to 2000 characters'; END IF; SELECT * INTO c FROM public.strategy_integrity_cases WHERE id=_case AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR c.status NOT IN('quarantined','upheld') THEN RAISE EXCEPTION 'Case cannot be appealed'; END IF; UPDATE public.strategy_integrity_cases SET status='appealed' WHERE id=c.id; INSERT INTO public.strategy_integrity_events(case_id,user_id,actor_id,action,message) VALUES(c.id,c.user_id,auth.uid(),'appealed',trim(_message)); END $$;
REVOKE ALL ON FUNCTION public.appeal_strategy_integrity(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.appeal_strategy_integrity(uuid,text) TO authenticated;
CREATE FUNCTION public.review_strategy_integrity(_case uuid,_decision text,_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.strategy_integrity_cases%ROWTYPE; BEGIN IF NOT public.account_mfa_allowed() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator review required'; END IF; IF _decision NOT IN('dismissed','upheld') OR length(trim(_message))<10 OR length(_message)>2000 THEN RAISE EXCEPTION 'Valid decision and 10 to 2000 character reason required'; END IF; SELECT * INTO c FROM public.strategy_integrity_cases WHERE id=_case FOR UPDATE; IF NOT FOUND OR c.status='dismissed' OR c.user_id=auth.uid() THEN RAISE EXCEPTION 'Independent reviewer required for an unresolved case'; END IF; UPDATE public.strategy_integrity_cases SET status=_decision,reviewed_at=now() WHERE id=c.id; INSERT INTO public.strategy_integrity_events(case_id,user_id,actor_id,action,message) VALUES(c.id,c.user_id,auth.uid(),_decision,trim(_message)); END $$;
REVOKE ALL ON FUNCTION public.review_strategy_integrity(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_strategy_integrity(uuid,text,text) TO authenticated;
CREATE TABLE public.strategy_promotion_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,bot_id uuid NOT NULL REFERENCES public.trading_bots(id),strategy_id uuid NOT NULL REFERENCES public.strategies(id),checklist jsonb NOT NULL,status text NOT NULL CHECK(status IN('blocked','review_required')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.strategy_promotion_reviews TO authenticated; GRANT ALL ON public.strategy_promotion_reviews TO service_role;
ALTER TABLE public.strategy_promotion_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY promotion_review_read ON public.strategy_promotion_reviews FOR SELECT TO authenticated USING(public.account_mfa_allowed() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE TRIGGER promotion_reviews_immutable BEFORE UPDATE OR DELETE ON public.strategy_promotion_reviews FOR EACH ROW EXECUTE FUNCTION public.prevent_evaluation_mutation();
COMMENT ON TABLE public.strategy_promotion_reviews IS 'Immutable eligibility checklists only; never grant trading authority or automatically activate bots';
COMMENT ON TABLE public.strategy_scoring_policies IS 'Versioned administrator-authored experimental utility anchors; partial evidence never yields a composite or live approval';